/**
 * Comparator for the routing condition
 */
export enum RoutingComparator {
  EQUAL = 'EQUAL',
  NOT_EQUAL = 'NOT_EQUAL',
  GREATER_THAN = 'GREATER_THAN',
  GREATER_THAN_OR_EQUAL = 'GREATER_THAN_OR_EQUAL',
  LESS_THAN = 'LESS_THAN',
  LESS_THAN_OR_EQUAL = 'LESS_THAN_OR_EQUAL',
  CONTAINS = 'CONTAINS',
  NOT_CONTAINS = 'NOT_CONTAINS',
  STARTS_WITH = 'STARTS_WITH',
  ENDS_WITH = 'ENDS_WITH',
  PATTERN = 'PATTERN',
  IN = 'IN',
  NOT_IN = 'NOT_IN',
  EXISTS = 'EXISTS',
}

/**
 * The type of the routing condition value
 */
export enum RoutingConditionType {
  STRING = 'string',
  NUMBER = 'number',
  BOOLEAN = 'boolean',
  COMMA_DELIMITED_LIST = 'comma-delimited-list',
  JSON_OBJECT = 'json-object',
  JSON_ARRAY = 'json-array',
}

export type AiResourceRoutingConditionValue = {
  /**
   * The type of the routing condition value
   */
  type: RoutingConditionType;
  /**
   * An optional expression EJS for the condition value
   */
  expression?: string;
};

export type AiResourceRoutingCondition = {
  /**
   * The type of the routing condition
   */
  type: 'condition';
  /**
   * The unique ID of the routing condition
   */
  id: string;
  /**
   * Label for the routing condition
   */
  label: string;
  /**
   * The EJS expression to evaluate for the condition
   */
  expression: string;
  /**
   * Comparator for the routing condition
   */
  comparator: RoutingComparator;
  /**
   * Value for the routing condition
   */
  value: AiResourceRoutingConditionValue;
};

